#include "g2m/layer/soil_rules.h"
#include "g2m/core/hash.h"
#include "strict_json.h"
#include <algorithm>
#include <cstdio>
#include <cstdlib>
#include <set>

namespace g2m {
namespace {
using json = nlohmann::json;
using strict::Reader;
// const unsigned char kSoilRulesDefault[]: the bytes of data/soil_rules/default.json, generated by CMake.
#include "soil_rules_default.inc"

bool cmp_holds(SoilCmp op, std::int64_t v, std::int64_t k) {
    switch (op) {
        case SoilCmp::Lt: return v < k;
        case SoilCmp::Le: return v <= k;
        case SoilCmp::Gt: return v > k;
        case SoilCmp::Ge: return v >= k;
    }
    return false;
}
} // namespace

void soil_normalise_texture(std::int32_t& sand, std::int32_t& silt, std::int32_t& clay) {
    const std::int64_t total = static_cast<std::int64_t>(sand) + silt + clay;
    if (total <= 0) { sand = silt = clay = 0; return; }
    const std::int32_t s = static_cast<std::int32_t>(static_cast<std::int64_t>(sand) * 1000 / total);
    const std::int32_t i = static_cast<std::int32_t>(static_cast<std::int64_t>(silt) * 1000 / total);
    sand = s; silt = i; clay = 1000 - s - i; // the remainder (at most 2 permille) goes to clay
}

std::uint8_t SoilRules::texture_code(std::int32_t sand, std::int32_t silt, std::int32_t clay) const {
    soil_normalise_texture(sand, silt, clay);
    if (sand == 0 && silt == 0 && clay == 0) return 0;
    for (const auto& cls : texture) {
        for (const auto& alt : cls.alternatives) {
            bool all = true;
            for (const auto& c : alt) {
                const std::int64_t v = static_cast<std::int64_t>(c.w[0]) * sand + static_cast<std::int64_t>(c.w[1]) * silt +
                                       static_cast<std::int64_t>(c.w[2]) * clay;
                if (!cmp_holds(c.op, v, c.k)) { all = false; break; }
            }
            if (all) return cls.code;
        }
    }
    return 0;
}

const SoilTextureClass* SoilRules::texture_by_code(std::uint8_t code) const {
    for (const auto& c : texture) if (c.code == code) return &c;
    return nullptr;
}

Result<SoilRules> load_soil_rules(std::span<const std::byte> bytes) {
    const char* begin = reinterpret_cast<const char*>(bytes.data());
    const json j = json::parse(begin, begin + bytes.size(), nullptr, /*allow_exceptions=*/false);
    if (j.is_discarded()) return make_error(ErrorCode::Malformed, "soil rules: not valid JSON");
    Reader rd;
    const auto fail = [&]() { return make_error(ErrorCode::InvalidArgument, "soil rules: " + rd.err); };
    if (!rd.keys(j, "root", {"format", "source", "grid", "nodata", "landcover", "horizons", "texture", "field_summary", "sources"})) return fail();
    std::string format;
    if (!rd.text(j, "root", "format", format)) return fail();
    if (format != "g2m.soil_rules/1") return make_error(ErrorCode::Unsupported, "soil rules: format '" + format + "'");
    SoilRules out;

    const auto* source = rd.field(j, "root", "source");
    if (!source || !rd.keys(*source, "source", {"scheme", "cells_per_degree"}) || !rd.text(*source, "source", "scheme", out.source_scheme) ||
        !rd.integer(*source, "source", "cells_per_degree", 1, 100000, out.cells_per_degree)) return fail();
    if (out.source_scheme.empty()) { rd.fail("source.scheme must not be empty"); return fail(); }
    const auto* grid = rd.field(j, "root", "grid");
    if (!grid || !rd.keys(*grid, "grid", {"cells_per_side"}) || !rd.integer(*grid, "grid", "cells_per_side", 4, 256, out.cells_per_side)) return fail();
    if (1024 % out.cells_per_side != 0) { rd.fail("grid.cells_per_side must divide 1024"); return fail(); }
    const auto* nodata = rd.field(j, "root", "nodata");
    if (!nodata || !rd.keys(*nodata, "nodata", {"surface_texture_sum_zero"}) ||
        !rd.boolean(*nodata, "nodata", "surface_texture_sum_zero", out.surface_texture_sum_zero_is_nodata)) return fail();

    const auto* lc = rd.field(j, "root", "landcover");
    if (!lc || !rd.keys(*lc, "landcover", {"scheme", "builtup", "water"}) || !rd.text(*lc, "landcover", "scheme", out.landcover_scheme)) return fail();
    for (const char* name : {"builtup", "water"}) {
        const auto* arr = rd.field(*lc, "landcover", name);
        if (!arr) return fail();
        if (!arr->is_array()) { rd.fail(std::string("landcover.") + name + " must be an array"); return fail(); }
        auto& dest = std::string(name) == "builtup" ? out.landcover_builtup : out.landcover_water;
        for (const auto& v : *arr) {
            if (!v.is_number_integer() || v.get<std::int64_t>() < 1 || v.get<std::int64_t>() > 255) {
                rd.fail(std::string("landcover.") + name + " entries must be integers in [1, 255]"); return fail();
            }
            dest.push_back(static_cast<std::uint8_t>(v.get<std::int64_t>()));
        }
        std::sort(dest.begin(), dest.end());
        if (std::adjacent_find(dest.begin(), dest.end()) != dest.end()) { rd.fail(std::string("landcover.") + name + " has a duplicate"); return fail(); }
    }
    for (std::uint8_t b : out.landcover_builtup)
        if (std::binary_search(out.landcover_water.begin(), out.landcover_water.end(), b)) { rd.fail("a land cover class is both built-up and water"); return fail(); }

    const auto* hz = rd.field(j, "root", "horizons");
    if (!hz || !hz->is_array() || hz->size() != kSoilHorizons) { rd.fail("horizons must be an array of exactly 2 entries (topsoil, subsoil)"); return fail(); }
    for (std::size_t i = 0; i < kSoilHorizons; ++i) {
        const std::string path = "horizons[" + std::to_string(i) + "]";
        const auto& e = (*hz)[i];
        SoilHorizonRule h;
        if (!rd.keys(e, path, {"name", "from_cm", "to_cm"}) || !rd.text(e, path, "name", h.name) || !rd.integer(e, path, "from_cm", 0, 199, h.from_cm) ||
            !rd.integer(e, path, "to_cm", 1, 200, h.to_cm)) return fail();
        if (h.name.empty() || h.from_cm >= h.to_cm) { rd.fail(path + ": needs a name and from_cm < to_cm"); return fail(); }
        out.horizons[i] = std::move(h);
    }
    if (out.horizons[0].to_cm > out.horizons[1].from_cm) { rd.fail("horizons must not overlap and must be ordered top first"); return fail(); }

    const auto* tex = rd.field(j, "root", "texture");
    if (!tex || !rd.keys(*tex, "texture", {"scheme", "classes"}) || !rd.text(*tex, "texture", "scheme", out.texture_scheme)) return fail();
    const auto* classes = rd.field(*tex, "texture", "classes");
    if (!classes || !classes->is_array() || classes->empty()) { rd.fail("texture.classes must be a non-empty array"); return fail(); }
    std::set<int> codes; std::set<std::string> names;
    for (std::size_t i = 0; i < classes->size(); ++i) {
        const std::string path = "texture.classes[" + std::to_string(i) + "]";
        const auto& e = (*classes)[i];
        SoilTextureClass c;
        std::int32_t code = 0;
        if (!rd.keys(e, path, {"code", "name", "alternatives"}) || !rd.integer(e, path, "code", 1, 254, code) || !rd.text(e, path, "name", c.name)) return fail();
        c.code = static_cast<std::uint8_t>(code);
        if (c.name.empty() || !codes.insert(code).second || !names.insert(c.name).second) { rd.fail(path + ": empty or duplicate name or code"); return fail(); }
        const auto* alts = rd.field(e, path, "alternatives");
        if (!alts || !alts->is_array() || alts->empty()) { rd.fail(path + ".alternatives must be a non-empty array"); return fail(); }
        for (std::size_t a = 0; a < alts->size(); ++a) {
            const std::string apath = path + ".alternatives[" + std::to_string(a) + "]";
            const auto& clauses = (*alts)[a];
            if (!clauses.is_array() || clauses.empty()) { rd.fail(apath + " must be a non-empty array of clauses"); return fail(); }
            std::vector<SoilClause> alt;
            for (std::size_t k = 0; k < clauses.size(); ++k) {
                const std::string cpath = apath + "[" + std::to_string(k) + "]";
                const auto& cl = clauses[k];
                if (!rd.keys(cl, cpath, {"w", "op", "k"})) return fail();
                const auto* w = rd.field(cl, cpath, "w");
                if (!w) return fail();
                if (!w->is_array() || w->size() != 3) { rd.fail(cpath + ".w must be an array of 3 integers"); return fail(); }
                SoilClause sc;
                for (std::size_t x = 0; x < 3; ++x) {
                    if (!(*w)[x].is_number_integer() || (*w)[x].get<std::int64_t>() < -1000 || (*w)[x].get<std::int64_t>() > 1000) {
                        rd.fail(cpath + ".w entries must be integers in [-1000, 1000]"); return fail();
                    }
                    sc.w[x] = static_cast<std::int32_t>((*w)[x].get<std::int64_t>());
                }
                std::string op;
                if (!rd.text(cl, cpath, "op", op)) return fail();
                if (op == "<") sc.op = SoilCmp::Lt; else if (op == "<=") sc.op = SoilCmp::Le; else if (op == ">") sc.op = SoilCmp::Gt;
                else if (op == ">=") sc.op = SoilCmp::Ge; else { rd.fail(cpath + ".op must be one of < <= > >="); return fail(); }
                std::int32_t kk = 0;
                if (!rd.integer(cl, cpath, "k", -2000000000, 2000000000, kk)) return fail();
                sc.k = kk;
                alt.push_back(sc);
            }
            c.alternatives.push_back(std::move(alt));
        }
        out.texture.push_back(std::move(c));
    }
    const auto* fs = rd.field(j, "root", "field_summary");
    if (!fs || !rd.keys(*fs, "field_summary", {"lattice_spacing_mm"}) ||
        !rd.integer(*fs, "field_summary", "lattice_spacing_mm", 1000, 256000, out.field_lattice_spacing_mm)) return fail();
    const auto* sources = rd.field(j, "root", "sources");
    if (!sources || !rd.object(*sources, "sources")) return fail();
    for (auto it = sources->begin(); it != sources->end(); ++it)
        if (!it.value().is_string()) { rd.fail("sources." + it.key() + " must be a string"); return fail(); }
    out.content_sha256 = Sha256::of(bytes);
    return out;
}

std::span<const std::byte> builtin_soil_rules_bytes() {
    return {reinterpret_cast<const std::byte*>(kSoilRulesDefault), sizeof(kSoilRulesDefault)};
}
const SoilRules& builtin_soil_rules() {
    static const SoilRules rules = [] {
        auto loaded = load_soil_rules(builtin_soil_rules_bytes());
        if (!loaded) {
            std::fprintf(stderr, "g2m: embedded data/soil_rules/default.json is invalid: %s\n", loaded.error().message.c_str());
            std::abort();
        }
        return std::move(*loaded);
    }();
    return rules;
}
} // namespace g2m
